// ─── PLAID API HELPERS ────────────────────────────────────────────────────────
async function callPlaid(action, params={}, options={}) {
  const headers = { "Content-Type": "application/json" };
  if (options.jwt) {
    headers["Authorization"] = `Bearer ${options.jwt}`;
  }
  const body = JSON.stringify({ action, ...params });
  // Quality Sprint item 6: retry transient failures (network drops + 502/503/504) with exponential
  // backoff. Client errors (4xx) and needs_reconnect surface immediately — retrying them is futile.
  // Quality Sprint review: only auto-retry idempotent/safe actions (reads, keyed upserts, idempotent
  // deletes). Non-idempotent mutations (exchange_token = single-use public_token) must NOT auto-retry
  // — a lost response could otherwise double-act. retries:0 still performs 1 attempt.
  const RETRY_SAFE = new Set(["create_link_token","get_accounts","get_transactions","get_liabilities","get_investments","list_items","migrate_items","delete_item","delete_account"]);
  const maxAttempts = Math.max(1, options.retries ?? (RETRY_SAFE.has(action) ? 3 : 1));
  let lastErr;
  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    if (attempt > 0) await new Promise(r => setTimeout(r, 400 * Math.pow(2, attempt - 1))); // 400ms, 800ms
    let res;
    try {
      res = await fetch(`${API_BASE}/api/plaid`, { method: "POST", headers, body });
    } catch (netErr) { lastErr = netErr; continue; } // network drop / offline → retry
    let data = {};
    try { data = await res.json(); } catch {}
    if (!res.ok) {
      if ((res.status === 502 || res.status === 503 || res.status === 504) && attempt < maxAttempts - 1) { lastErr = new Error(data.error || "server busy"); continue; }
      const err = new Error(data.error || "Plaid error");
      err.needs_reconnect = data.needs_reconnect || false;
      if (data.needs_reconnect && typeof window.__flourishReconnect === "function") window.__flourishReconnect();
      throw err;
    }
    return data;
  }
  // Sprint Z #10: report the final failure (retries exhausted / network) once, for all Plaid calls.
  const _finalErr = (lastErr || new Error("Network error. Please check your connection."));
  captureError(_finalErr, { area: "plaid", extra: { action } });
  throw _finalErr;
}

// Phase D1: persist Plaid Item to Supabase via authenticated server call.
// Phase 1.2: storePlaidItemServerSide removed — exchange_token now exchanges AND
// persists the Plaid item server-side atomically, so the client never handles or
// round-trips an access_token.

// Phase D1-E: one-time migration of existing localStorage tokens to Supabase.
// Idempotent on the server side (upsert by user_id+item_id), so safe to re-run.
// Marks completion in localStorage to skip on subsequent sessions.
//
// Phase D6 note: this is the LAST consumer of localStorage["flourish_plaid_token*"]
// keys. Once we're confident every beta user has set flourish_d1e_migrated=1,
// this function and its call site can be retired and the legacy keys deleted.
async function migrateLocalStorageTokensToSupabase() {
  if (localStorage.getItem("flourish_d1e_migrated") === "1") return;
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session?.access_token) return; // user not authenticated yet — try next session

    // Defensive merge of legacy single-token + multi-bank array
    const arr = (() => {
      try { return safeLoadLS("flourish_plaid_tokens", null); }
      catch { return null; }
    })();
    const legacy = localStorage.getItem("flourish_plaid_token");
    const merged = [];
    if (Array.isArray(arr)) {
      for (const e of arr) if (e?.token) merged.push({ token: e.token, institution_name: e.institution || "Your Bank" });
    }
    if (legacy && !merged.some(m => m.token === legacy)) {
      merged.push({ token: legacy, institution_name: "Your Bank" });
    }

    if (merged.length === 0) {
      // No tokens to migrate — mark done and exit
      localStorage.setItem("flourish_d1e_migrated", "1");
      return;
    }

    const resp = await callPlaid("migrate_items", { tokens: merged }, { jwt: session.access_token });
    const successes = resp.successes || [];
    const failures = resp.failures || [];
    console.log(`[d1e] migrated ${successes.length} tokens, ${failures.length} failures`);
    // Mark done regardless — failures are recorded server-side as status:active rows that
    // failed /item/get, OR they're tokens that revoked at the bank. User will re-link if needed.
    localStorage.setItem("flourish_d1e_migrated", "1");
  } catch (err) {
    // Transient failure — don't set flag, retry next session
    console.warn("[d1e] migration failed (will retry next session)", err.message);
  }
}

// Phase D1-F-B: fetch the current Supabase JWT for authenticated server calls.
async function getJwt() {
  try {
    const { data: { session } } = await supabase.auth.getSession();
    return session?.access_token || null;
  } catch { return null; }
}

