// Module-level, NOT component state, so "at most once per session" survives the AICoach component
// unmounting and remounting within a single page load. A full reload is a new session and resets it.
let _coachConsentHealAttempted = false;
const coachHealAttempted = () => _coachConsentHealAttempted;
const markCoachHealAttempted = () => { _coachConsentHealAttempted = true; };
// The localStorage flag acceptAIDisclosure sets — the sole signal that the user previously accepted.
const readLocalAIConsent = () => {
  try { return localStorage.getItem("flourish_ai_third_party_consent") === "1"; } catch { return false; }
};

// US states that levy NO personal income tax on WAGES for the 2026 tax year (verified against the Tax
// Foundation 2026 tables and state revenue departments). Classified for a wage-earner audience —
// salary is untaxed in all nine:
//   AK, FL, NV, SD, TX, WY — no personal income tax of any kind.
//   TN — Hall tax (interest/dividends) fully repealed in 2021; nothing since.
//   NH — never taxed wages; its last levy, the Interest & Dividends tax, was repealed effective
//        Jan 1 2025, so for 2026 it taxes no personal income at all.
//   WA — no wage tax; taxes only high-value long-term capital gains via a 7% EXCISE tax (upheld as
//        non-income by the WA Supreme Court, Quinn v. State). Untaxed for a wage earner.
// The old check whitelisted only TX/FL/WA, so residents of the other six were wrongly told state
// income tax applied.
const NO_STATE_WAGE_TAX = new Set(["AK", "FL", "NV", "NH", "SD", "TN", "TX", "WA", "WY"]);


// Sprint Z #1 (B1 safety net): the server persists the per-item cursor, so a delta dropped before
// the client applied it (lost response, app killed mid-save) could otherwise be stranded forever.
// Force a full resync at least weekly to self-heal any such gap (mergeById makes a re-pull idempotent).
const FULL_SYNC_STALE_MS = 7 * 24 * 60 * 60 * 1000;
function isFullSyncStale() {
  try { return (Date.now() - parseInt(localStorage.getItem("flourish_last_full_sync") || "0", 10)) > FULL_SYNC_STALE_MS; } catch { return false; }
}
function stampFullSync() {
  try { localStorage.setItem("flourish_last_full_sync", Date.now().toString()); } catch {}
}

// Sprint Z #3: drain a truncated sync within one cycle. The server caps pages per call and flags
// `truncated`; we keep calling for the item (the persisted cursor resumes) until it's complete,
// so the user never sees partial history waiting on the next throttled refresh. Bounded guard.
async function fetchItemTxns(item_id, jwt, fullResync) {
  const transactions = [];
  const removed = [];
  let full = false;
  let resync = !!fullResync;
  for (let guard = 0; guard < 12; guard++) {
    const resp = await callPlaid("get_transactions", { item_id, days: 90, full_resync: resync }, { jwt });
    if (Array.isArray(resp.transactions)) transactions.push(...resp.transactions);
    if (Array.isArray(resp.removed)) removed.push(...resp.removed);
    full = full || !!resp.full;
    if (!resp.truncated) break;
    resync = false; // subsequent pages resume from the persisted cursor, never re-full
  }
  return { transactions, removed, full };
}

// Phase D1-F-B: fetch the user's connected Plaid items (metadata only — no access_tokens).
// Used by multi-bank fan-out sites to drive get_transactions/accounts/etc. via item_id + JWT.
async function getUserItems() {
  const jwt = await getJwt();
  if (!jwt) return [];
  try {
    const resp = await callPlaid("list_items", {}, { jwt });
    return resp.items || [];
  } catch (err) {
    console.warn("[getUserItems] failed", err.message);
    return [];
  }
}

// Plaid Personal Finance Category (PFC) primary values → Flourish display meta
// Shared keyword list for detecting credit card payments in transactions.
// Used by income detection, spending calc, and transparency panel — single source of truth.
// Sprint MATH-LOCK: CC/transfer constants, BILL_CATS/NON_SPEND_CATS, isInternalTransfer,
// isCCPayment, isCashAdvance, and CAT_META moved to financialCalculations.js (imported above).

// Sprint MATH-LOCK Group C: normaliseTxns + detectIncomeFromTxns moved to plaidNormalize.js (imported above).

// Small Levenshtein for fuzzy bill-name dedupe (Tier 4). Inputs are short merchant names.
// Sprint 4b: corruption-safe localStorage JSON read. A malformed value (a truncated write,
// manual tampering, or quota eviction mid-write) returns the fallback instead of throwing —
// previously an unguarded JSON.parse in a render path could white-screen the whole app.
function safeLoadLS(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (raw == null) return fallback;
    const v = JSON.parse(raw);
    return v == null ? fallback : v;
  } catch { return fallback; }
}

// Sprint MATH-LOCK Group B: per-transaction category reassignments { txnId: category }. Loads the
// EXACT value FinancialCalcEngine.cashFlow used to read internally — passed into the now-pure engine
// at every call site so re-categorization keeps affecting cash-flow/spend math (no silent {} drop).
// Two layers, most specific first: an override on THIS transaction, then a rule for the
// merchant. The merchant layer is what makes a correction outlive the row it was made on —
// see src/lib/categoryOverrides.js. Engines take the pair and resolve it themselves.
const getCatOvById = () => safeLoadLS("flourish_cat_overrides", {});
const getMerchantCatOv = () => safeLoadLS("flourish_cat_merchant_overrides", {});
const getCatOv = () => ({ byId: getCatOvById(), byMerchant: getMerchantCatOv() });
// For display paths that already hold a byId map of their own.
//
// Memoised: called per transaction, several times per render across the whole list, and
// getMerchantCatOv is a localStorage read plus a JSON.parse — what it replaced was a property
// read. bumpMerchantCatOv() clears it on every write, so a correction shows immediately; without
// that, seeing your own change would take a reload.
let _mcoCache = null;
const getMerchantCatOvCached = () => (_mcoCache || (_mcoCache = getMerchantCatOv()));
const bumpMerchantCatOv = () => { _mcoCache = null; };
const effCat = (t, byId) => effectiveCategory(t, byId, getMerchantCatOvCached());

// Sprint MATH-LOCK Group C: _levenshtein moved to plaidNormalize.js (used by detectRecurringBills).

// Sprint MATH-LOCK: isBillArchived (now with a threaded `today` for testability) moved to
// financialCalculations.js (imported above).

// Tier 5: single source of truth for removing a bill — drops it AND records the merchant in
// userBillOverrides.removed so auto-detection never re-adds it. Shared by every remove surface.
function removeBillWithOverride(setAppData, idx, name) {
  if (!setAppData) return;
  const norm = String(name || "").toLowerCase().trim();
  setAppData(prev => {
    const ov = prev.userBillOverrides || {};
    return {
      ...prev,
      bills: (prev.bills || []).filter((_, x) => x !== idx),
      userBillOverrides: { removed: Array.from(new Set([...(ov.removed || []), norm])).filter(Boolean), typed: ov.typed || {}, cadence: ov.cadence || {}, amounts: ov.amounts || {} },
    };
  });
}


