// ─── Plaid Link SDK hook ──────────────────────────────────────────────────────
// Loads Plaid CDN script once. Uses a ref for onSuccess so the handler is
// never stale even if the callback closes over fresh state.
function usePlaidLinkSDK(linkToken, onSuccess) {
  const [sdkReady, setSdkReady] = useState(false);
  const [sdkError, setSdkError] = useState(false);
  const onSuccessRef = useRef(onSuccess);
  useEffect(() => { onSuccessRef.current = onSuccess; }, [onSuccess]);

  useEffect(() => {
    if (window.Plaid) { setSdkReady(true); return; }
    const SRC = "https://cdn.plaid.com/link/v2/stable/link-initialize.js";
    // Dedupe: another usePlaidLinkSDK instance may have already injected the script.
    let script = document.querySelector(`script[src="${SRC}"]`);
    const onLoad  = () => setSdkReady(true);
    const onError = () => setSdkError(true);
    if (script) {
      // Script already injected by sibling hook. Attach listeners; if it's already loaded, fire immediately.
      script.addEventListener("load", onLoad);
      script.addEventListener("error", onError);
      if (window.Plaid) setSdkReady(true);
    } else {
      script = document.createElement("script");
      script.src = SRC;
      script.addEventListener("load", onLoad);
      script.addEventListener("error", onError);
      document.head.appendChild(script);
    }
    return () => {
      script.removeEventListener("load", onLoad);
      script.removeEventListener("error", onError);
    };
  }, []);

  const openPlaidLink = useCallback(() => {
    if (!sdkReady || !window.Plaid || !linkToken) return;
    window.Plaid.create({
      token: linkToken,
      onSuccess: (...args) => onSuccessRef.current(...args),
      onExit: (err, meta) => { if (err) console.warn("Plaid exit:", err, meta); },
    }).open();
  }, [sdkReady, linkToken]);

  return { openPlaidLink, plaidReady: sdkReady && !!linkToken, plaidSdkError: sdkError };
}


// The demo household's accounts, debts and profile now live with the rest of the demo data in
// lib/demoFixture.js, keyed by country. MOCK_ACCOUNTS_US used to sit here unreferenced, with the
// Canadian balances copied verbatim onto American account names — the "relabelled copy" the US
// fixture deliberately is not.
// App Store screenshot / review account. On login this email loads a populated demo state directly
// (see the hydrate effect) instead of reading the DB — so it always lands on a full dashboard,
// bypassing the hydrate-vs-onboarding race that kept clobbering a DB-seeded account.
const SCREENSHOT_EMAIL = "snap@flourish.app";

// Defaults for profile.notifications (nested like profile.meetingSchedule). All types default on, but
// nothing fires until permission is granted — these toggles govern WHAT gets scheduled once it is.
const NOTIF_DEFAULTS = { permissionAsked:false, billDue:true, lowBalance:true, unusualAmount:true, meetingReminder:true };

// Reconcile the OS-scheduled notifications to match current data + toggles + permission. Runs
// (debounced) whenever notification-relevant data changes. Strategy: cancel-all-of-type, then
// reschedule the desired set. Because planNotifications derives every fire time from stored data
// (never from `now`) and ids are stable (notifId), this is idempotent — an edit overwrites, a removed
// bill's reminder disappears, and re-running with unchanged data produces the identical schedule.
async function reconcileNotifications(data) {
  const TYPES = ["billDue", "lowBalance", "unusualAmount", "meetingReminder"];
  const perm = await getNotificationPermission();
  const toggles = { ...NOTIF_DEFAULTS, ...(data?.profile?.notifications || {}) };
  // Never schedule without permission — and clear anything stale if permission was revoked.
  if (!perm.granted) { for (const ty of TYPES) await cancelAllOfType(ty); return; }
  const desired = planNotifications(data, new Date());
  for (const ty of TYPES) {
    await cancelAllOfType(ty);
    if (!toggles[ty]) continue;                    // toggle off → leave the type cleared
    for (const n of desired.filter(d => d.type === ty)) {
      await scheduleNotification({ id: n.id, type: n.type, title: n.title, body: n.body, at: n.at });
    }
  }
}

// Sprint Z #15: the demo/sample state, shared by the onboarding "Try Demo" button and the
// empty-dashboard "Try with demo data" CTA. demo:true → never synced to the DB and surfaces the
// persistent demo banner. Lets an App Store reviewer exercise the full app with no real bank login.
// `country` selects WHICH synthetic household is loaded — a US visitor gets a US one (checking, a
// 401(k), a federal student loan, no child benefit), not the Canadian household with the words
// swapped. It also sets profile.country, which is the single value every locale-gated string and
// baseCurrencyOf() already read, so the whole demo session resolves to that country by construction
// rather than by a second switch anywhere else. An unknown value falls back to CA inside the fixture.
function buildDemoState(country = "CA") {
  const cc = DEMO_COUNTRIES.includes(String(country || "").toUpperCase()) ? String(country).toUpperCase() : "CA";
  return {
    profile:demoProfileFor(cc),
    // Phase-anchored so a visitor always lands at the same point in the pay cycle (see demoFixture.js).
    incomes:buildDemoIncomes(new Date(), cc),
    bills:buildDemoBills(new Date(), cc),
    debts:demoDebtsFor(cc),
    accounts:demoAccountsFor(cc),
    transactions:buildDemoTxns(new Date(), cc),
    bankConnected:true,
    demo:true,
  };
}

