// ── DECISION ENGINE ─────────────────────────────────────────────────────────────
function DecisionEngine({data, safe, bal, monthlyIncome, soonBills, todayDate, dailyPace, setScreen}) {
  const bills = data.bills || [];
  const debts = data.debts || [];

  // Sprint MATH-LOCK Group F: pure decision math lives in lib/decisionEngine.js (tested there); this
  // component calls the helpers, then builds the themed advice cards (colors/labels) below.
  const todayD = todayDate instanceof Date ? todayDate : new Date();
  // Truth-fix items 2 and 4: the real next deposit (date + per-deposit amount), as the household corrected it.
  const daysToPayday = daysToNextDepositFor(data, todayD);
  const nextDep = nextDepositFor(data, todayD);
  // Consolidation 1: the suggested daily figure is owned by suggestedDailyView and passed in as dailyPace,
  // so Today and Decisions show the SAME number (this card used to divide safe by a 14-floored divisor here).
  const topDebt = selectHighestRateDebt(debts);
  const extraPayment = 150;
  const monthsSaved = computeDebtPayoffImpact(topDebt, extraPayment);
  const safeToMove = computeSavingsOpportunity(safe);
  const lowCash = detectLowCashWarning(safe, monthlyIncome);

  // Build decision cards
  const decisions = [];
  if (dailyPace.daily > 0) {
    decisions.push({
      type: "daily",
      icon: "💡",
      color: C.teal,
      title: `Suggested spend today: ${dailyPace.dailyText}`,
      detail: nextDep
        ? ((daysToPayday != null && daysToPayday <= 1)
            ? `Keeps you safe until tomorrow's deposit of ${formatMoney(nextDep.amount)}.`
            : `Keeps you safe until your next deposit of ${formatMoney(nextDep.amount)} on ${nextDep.date.toLocaleDateString("en-CA", { month: "short", day: "numeric" })}.`)
        // "deposit", not "paycheque" — the same fix as the forecast rows, and this branch is the one
        // that fires when NO deposit could be projected at all, i.e. exactly when the app knows least
        // about what is coming. Its sibling branch two lines up already says "deposit".
        : "Keeps you safe until your next deposit.",
      action: "See forecast", screen: "plan"
    });
  }
  if (lowCash) {
    decisions.push({
      type: "warning",
      icon: "⚠️",
      color: C.orange,
      title: "Cash is running tight",
      detail: `Your balance is below 15% of monthly income. Hold non-essential spending for ${daysToPayday != null ? daysToPayday : "a few"} days.`,
      action: "See Plan", screen: "plan"
    });
  }
  if (safeToMove > 20) {
    decisions.push({
      type: "savings",
      icon: "💚",
      color: C.green,
      title: `Move $${safeToMove} to savings`,
      detail: "You can do this now and still stay safe until your next deposit.",
      action: "See Goals", screen: "goals"
    });
  }
  if (topDebt && monthsSaved > 0) {
    decisions.push({
      type: "debt",
      icon: "🎯",
      color: C.purple,
      title: `Pay $${extraPayment} extra on ${topDebt.name}`,
      detail: `Cuts ${monthsSaved} month${monthsSaved!==1?"s":""} off your payoff date. Worth more than any subscription cancel.`,
      action: "Debt Plan", screen: "goals"
    });
  }

  if (decisions.length === 0) return null;

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
        <div style={{color:C.cream,fontSize:13,fontWeight:700,fontFamily:"'Plus Jakarta Sans',sans-serif",display:"flex",alignItems:"center",gap:7}}>
          <Icon id="zap" size={15} color={C.goldBright} strokeWidth={2}/>
          What to do today
        </div>
        <span style={{color:C.muted,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>Decision Engine</span>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {decisions.map((d,i)=>(
          <button key={i} onClick={()=>setScreen(d.screen)} style={{background:C.card,border:`1.5px solid ${d.color}28`,borderRadius:18,padding:"14px 16px",cursor:"pointer",textAlign:"left",fontFamily:"inherit",display:"flex",gap:12,alignItems:"flex-start",transition:"all .2s",width:"100%"}}
            onMouseEnter={e=>{e.currentTarget.style.borderColor=d.color+"66";e.currentTarget.style.background=d.color+"0A";}}
            onMouseLeave={e=>{e.currentTarget.style.borderColor=d.color+"28";e.currentTarget.style.background=C.card;}}>
            <span style={{fontSize:20,flexShrink:0,marginTop:1}}>{d.icon}</span>
            <div style={{flex:1,minWidth:0}}>
              <div style={{color:d.color,fontWeight:700,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",marginBottom:3}}>{d.title}</div>
              <div style={{color:C.muted,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",lineHeight:1.55}}>{d.detail}</div>
            </div>
            <div style={{color:d.color,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,whiteSpace:"nowrap",marginTop:3}}>{d.action} →</div>
          </button>
        ))}
      </div>
    </div>
  );
}


