// ── ENGINE 1: FINANCIAL CALCULATION ENGINE ────────────────────────────────────
// Computes all core financial metrics from raw user data.

// Sprint MATH-LOCK Group B: FinancialCalcEngine moved to financialCalculations.js (imported above).
// cashFlow/savingsRate/debtRatio/emergencyFundMonths now take (data, catOverrides, currentDate).
// Call sites pass getCatOv() (the same flourish_cat_overrides load the engine did internally) so the
// re-categorization feature is preserved; currentDate defaults to now (behavior-preserving).

// ── ENGINE 2: SAFE-SPEND ENGINE — moved to lib/safeSpendEngine.js (Sprint MATH-LOCK Group D) ──

// ── ENGINE 3: 90-DAY CASH FLOW FORECAST — moved to lib/forecastEngine.js (Sprint MATH-LOCK Group E) ──

// ── ENGINES 4 & 5: BehaviorEngine, AutopilotEngine, calcHealthScore (ProsperityEngine) —
//    moved to lib/decisionEngine.js (Sprint MATH-LOCK Group F). HealthScoreRing (below) is the
//    UI component that renders calcHealthScore's output and stays here.

function HealthScoreRing({score, size=110, strokeW=9, bonus=0}) {
  const [displayed, setDisplayed] = useState(0);
  useEffect(() => {
    let start = 0;
    const step = Math.ceil(score / 40);
    const t = setInterval(() => {
      start = Math.min(start + step, score);
      setDisplayed(start);
      if (start >= score) clearInterval(t);
    }, 22);
    return () => clearInterval(t);
  }, [score]);
  const r = (size - strokeW * 2) / 2;
  const circ = 2 * Math.PI * r;
  const progress = (displayed / 100) * circ;
  const grade = score >= 80 ? "Excellent" : score >= 65 ? "Good" : score >= 50 ? "Fair" : score >= 35 ? "Needs Work" : "Critical";
  const gradeColor = score >= 80 ? C.greenBright : score >= 65 ? C.tealBright : score >= 50 ? C.goldBright : score >= 35 ? C.orangeBright : C.redBright;
  const gId = "hsr" + size + score;
  return (
    <div style={{position:"relative", width:size, height:size, flexShrink:0}}>
      <svg width={size} height={size} style={{transform:"rotate(-90deg)", display:"block"}}>
        <defs>
          <linearGradient id={gId} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor={score>=65?C.green:C.gold}/>
            <stop offset="100%" stopColor={gradeColor}/>
          </linearGradient>
        </defs>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth={strokeW}/>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={"url(#"+gId+")"}
          strokeWidth={strokeW} strokeDasharray={`${progress} ${circ}`}
          strokeLinecap="round" style={{transition:"stroke-dasharray 0.05s linear"}}/>
      </svg>
      <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:0}}>
        <div style={{fontSize:Math.round(size*0.27),fontWeight:900,color:gradeColor,fontFamily:"'Playfair Display',serif",lineHeight:1}}>{displayed}</div>
        <div style={{fontSize:Math.max(TYPE_MIN,Math.round(size*0.094)),color:C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,lineHeight:1.3}}>{grade}</div>
        {bonus>0&&<div style={{fontSize:Math.max(TYPE_MIN,Math.round(size*0.082)),color:C.greenBright,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:700,marginTop:1}}>+{bonus} ✦</div>}
      </div>
    </div>
  );
}

function WeeklyCheckInModal({data, onClose, onComplete}) {
  const [step, setStep] = useState(0);
  const [mood, setMood] = useState(null);
  const [surprise, setSurprise] = useState("");
  const [win, setWin] = useState("");
  const [insight, setInsight] = useState(null);
  const [insightError, setInsightError] = useState(null); // the tip failed; the check-in itself did not
  const [loading, setLoading] = useState(false);

  const moods = [
    {emoji:"😰", label:"Stressed", val:1},
    {emoji:"😕", label:"Uneasy",   val:2},
    {emoji:"😐", label:"Neutral",  val:3},
    {emoji:"🙂", label:"Okay",     val:4},
    {emoji:"😄", label:"Great",    val:5},
  ];

  const surpriseOpts = ["Eating out","Subscriptions","Shopping","Fuel / Transit","Impulse buy","Medical","Entertainment","Other"];
  const winOpts = ["Skipped a purchase","Paid a bill early","Saved something","Stuck to budget","Paid extra on debt","Nothing yet"];

  const fetchInsight = async () => {
    setLoading(true);
    const txns = (data.transactions || []).slice(0, 15).map(t=>`${sanitizeField(t.name||t.merchant||"Purchase",80)} $${Math.abs(parseFloat(t.amount)||0)}`).join(", ");
    const {score} = calcHealthScore(data, getCatOv());
    // Sprint 3: send the user's data as `context` (the server wraps it in UNTRUSTED_USER_DATA
    // INSIDE the system prompt) and a fixed instruction as the user-role `prompt` — so untrusted
    // transaction text never rides in the user turn.
    const context = `Financial Health Score: ${score}/100. Money mood this week: ${moods.find(m=>m.val===mood)?.label||"Neutral"}. Biggest spending surprise: ${sanitizeField(surprise||"none",60)}. Financial win: ${sanitizeField(win||"none",60)}. Recent transactions: ${txns}`;
    const prompt = "The user just completed their weekly money check-in. Using only the data provided, give ONE specific, encouraging action they can take this week to improve their Financial Health Score by 2-5 points. Keep it to 2 sentences max. Be warm and concrete.";
    setInsightError(null);
    try {
      // Phase D3: AI opt-out — skip the AI tip; the catch below says so rather than inventing one
      ensureAiEnabled("AI disabled"); // Step 8: single gate — no request reaches /api/coach when AI is off
      const _jwt = await getJwt();
      const r = await fetch(`${API_BASE}/api/coach`, {
        method:"POST",
        headers:{"Content-Type":"application/json", Authorization:`Bearer ${_jwt}`},
        body: JSON.stringify({ type:"checkin", payload:{ context, prompt } })
      });
      // Item 6: check r.ok BEFORE reading. Without it a 429, a 401 or a 500 all parsed to an empty
      // body and the || below printed a specific piece of coaching advice — pause a subscription —
      // that the coach never gave. The catch below says plainly that there is no tip this time.
      if (!r.ok) throw new Error(`coach ${r.status}`);
      const d = await r.json();
      const tip = d.content?.[0]?.text;
      if (!tip || !String(tip).trim()) throw new Error("coach empty");
      setInsight(tip);
    } catch (e) {
      if (e?.message !== "AI disabled") captureError(e, { area: "coach" });
      // Not a coaching line. The old text invented advice AND a dollar figure ($20) that no engine
      // computed, under the coach's name, whenever the request failed. The check-in itself still
      // succeeded, so the result step still shows — it just says there is no tip this time.
      // Not "your check-in is saved": nothing is persisted here. The +3 lands only when the person
      // taps Done on this step, so the copy points at that rather than implying it is already done.
      setInsightError(e?.message === "AI disabled"
        ? "The coach is off in Settings, so there's no tip this time. Tap Done to record your check-in."
        : "The coach didn't answer, so there's no tip this time. Tap Done to record your check-in.");
    }
    setLoading(false);
    setStep(4);
  };

  const steps = [
    // Step 0: Mood
    <div key={0} style={{display:"flex",flexDirection:"column",gap:20}}>
      <div style={{textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>💚</div>
        <div style={{fontFamily:"'Playfair Display',serif",fontSize:22,fontWeight:900,color:C.cream,lineHeight:1.2}}>How do you feel about money this week?</div>
      </div>
      <div style={{display:"flex",gap:10,justifyContent:"center",flexWrap:"wrap"}}>
        {moods.map(m=>(
          <button key={m.val} onClick={()=>setMood(m.val)} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6,padding:"14px 12px",borderRadius:18,border:`2px solid ${mood===m.val?C.green+"88":C.border}`,background:mood===m.val?C.greenDim:C.card,cursor:"pointer",minWidth:60,transition:"all .15s"}}>
            <span style={{fontSize:28}}>{m.emoji}</span>
            <span style={{fontSize:13,color:mood===m.val?C.green:C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600}}>{m.label}</span>
          </button>
        ))}
      </div>
      <button onClick={()=>mood&&setStep(1)} style={{background:mood?`linear-gradient(135deg,${C.green},${C.greenBright})`:"#e0e0e0",color:mood?"#fff":C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:800,fontSize:15,padding:"14px",borderRadius:99,border:"none",cursor:mood?"pointer":"default",transition:"all .2s"}}>Next →</button>
    </div>,

    // Step 1: Surprise
    <div key={1} style={{display:"flex",flexDirection:"column",gap:20}}>
      <div style={{textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>💸</div>
        <div style={{fontFamily:"'Playfair Display',serif",fontSize:20,fontWeight:900,color:C.cream,lineHeight:1.3}}>What was your biggest spending surprise?</div>
      </div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
        {surpriseOpts.map(o=>(
          <button key={o} onClick={()=>setSurprise(o)} style={{padding:"12px 10px",borderRadius:14,border:`1.5px solid ${surprise===o?C.orange+"99":C.border}`,background:surprise===o?C.orangeDim:C.card,color:surprise===o?C.orange:C.mutedHi,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,fontSize:13,cursor:"pointer",transition:"all .15s"}}>{o}</button>
        ))}
      </div>
      <div style={{display:"flex",gap:10}}>
        <button onClick={()=>setStep(0)} style={{flex:1,padding:"13px",borderRadius:99,border:`1px solid ${C.border}`,background:"none",color:C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,cursor:"pointer"}}>← Back</button>
        <button onClick={()=>setStep(2)} style={{flex:2,background:`linear-gradient(135deg,${C.green},${C.greenBright})`,color:"#021208",fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:800,fontSize:15,padding:"13px",borderRadius:99,border:"none",cursor:"pointer"}}>Next →</button>
      </div>
    </div>,

    // Step 2: Win
    <div key={2} style={{display:"flex",flexDirection:"column",gap:20}}>
      <div style={{textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:8}}>🏆</div>
        <div style={{fontFamily:"'Playfair Display',serif",fontSize:20,fontWeight:900,color:C.cream,lineHeight:1.3}}>Share one financial win this week</div>
        <div style={{color:C.muted,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",marginTop:6}}>Every small step counts.</div>
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {winOpts.map(o=>(
          <button key={o} onClick={()=>setWin(o)} style={{padding:"12px 16px",borderRadius:14,border:`1.5px solid ${win===o?C.green+"99":C.border}`,background:win===o?C.greenDim:C.card,color:win===o?C.green:C.mutedHi,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,fontSize:13,cursor:"pointer",textAlign:"left",transition:"all .15s"}}>
            {win===o?"✓ ":""}{o}
          </button>
        ))}
      </div>
      <div style={{display:"flex",gap:10}}>
        <button onClick={()=>setStep(1)} style={{flex:1,padding:"13px",borderRadius:99,border:`1px solid ${C.border}`,background:"none",color:C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:600,cursor:"pointer"}}>← Back</button>
        <button onClick={fetchInsight} style={{flex:2,background:`linear-gradient(135deg,${C.green},${C.greenBright})`,color:"#021208",fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:800,fontSize:15,padding:"13px",borderRadius:99,border:"none",cursor:"pointer"}}>{loading?"Getting your coaching...":"Get My Insight →"}</button>
      </div>
    </div>,

    // Step 4: Result (loading is step 3, handled inline)
    (insight || insightError) && <div key={4} style={{display:"flex",flexDirection:"column",gap:20,textAlign:"center"}}>
      <div style={{fontSize:48,animation:"fadeUp 0.4s ease both"}}>✦</div>
      <div style={{fontFamily:"'Playfair Display',serif",fontSize:22,fontWeight:900,color:C.green,lineHeight:1.2}}>Check-In Complete!</div>
      {insight ? (
        <div style={{background:C.greenDim,border:`1.5px solid ${C.green}33`,borderRadius:20,padding:"18px 20px",textAlign:"left"}}>
          <div style={{color:C.green,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:700,marginBottom:8}}>Your AI Coach Says</div>
          <div style={{color:C.cream,fontSize:14,lineHeight:1.7,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>{insight}</div>
        </div>
      ) : (
        <div style={{background:C.cardAlt,border:`1px solid ${C.border}`,borderRadius:20,padding:"18px 20px",textAlign:"left"}}>
          <div style={{color:C.mutedHi,fontSize:13.5,lineHeight:1.7,fontFamily:"'Plus Jakarta Sans',sans-serif"}}>{insightError}</div>
          <button onClick={fetchInsight} disabled={loading} style={{marginTop:12,background:"none",border:`1px solid ${C.green}66`,borderRadius:10,padding:"8px 16px",color:C.greenBright,fontWeight:700,fontSize:13,cursor:loading?"default":"pointer",fontFamily:"inherit"}}>{loading?"Trying…":"Try again"}</button>
        </div>
      )}
      <div style={{background:`linear-gradient(135deg,${C.green}18,${C.greenDim})`,border:`1px solid ${C.green}33`,borderRadius:18,padding:"16px"}}>
        <div style={{fontSize:28,marginBottom:4}}>🎯</div>
        <div style={{color:C.green,fontWeight:800,fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:16}}>Financial Health Score</div>
        <div style={{color:C.greenBright,fontWeight:900,fontFamily:"'Playfair Display',serif",fontSize:32,marginTop:4}}>+3 points this week ✦</div>
        <div style={{color:C.muted,fontSize:13,fontFamily:"'Plus Jakarta Sans',sans-serif",marginTop:4}}>Check in every week to keep growing</div>
      </div>
      <button onClick={()=>onComplete(3)} style={{background:`linear-gradient(135deg,${C.green},${C.greenBright})`,color:"#021208",fontFamily:"'Plus Jakarta Sans',sans-serif",fontWeight:800,fontSize:15,padding:"16px",borderRadius:99,border:"none",cursor:"pointer",boxShadow:`0 6px 20px ${C.green}40`}}>Done. See My Score ✦</button>
    </div>,
  ];

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.55)",backdropFilter:"blur(6px)",zIndex:999,display:"flex",alignItems:window.innerWidth>900?"center":"flex-end",justifyContent:"center",padding:"0 0 0 0"}} onClick={e=>e.target===e.currentTarget&&onClose()}>
      <div style={{background:C.bg,borderRadius:"28px 28px 0 0",padding:"28px 24px 40px",width:"100%",maxWidth:520,maxHeight:"88vh",overflowY:"auto",boxShadow:"0 -20px 60px rgba(0,0,0,0.2)"}}>
        {/* Step indicator */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:24}}>
          <div style={{display:"flex",gap:6}}>
            {[0,1,2,3].map(i=>(
              <div key={i} style={{width:i<=(step===4?3:step)?28:8,height:8,borderRadius:99,background:i<=(step===4?3:step)?C.green:C.border,transition:"all .3s"}}/>
            ))}
          </div>
          <button aria-label="Close" onClick={onClose} style={{background:"none",border:"none",color:C.muted,fontSize:22,cursor:"pointer",padding:"4px 8px",lineHeight:1}}>×</button>
        </div>
        {loading
          ? <div style={{textAlign:"center",padding:"40px 20px"}}>
              <div style={{fontSize:40,marginBottom:16,animation:"spin 1s linear infinite"}}>💚</div>
              <div style={{color:C.cream,fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:16,fontWeight:600}}>Analyzing your week...</div>
              <div style={{color:C.muted,fontFamily:"'Plus Jakarta Sans',sans-serif",fontSize:13,marginTop:8}}>Building your personalized insight</div>
            </div>
          : steps[step===4?3:step]
        }
      </div>
    </div>
  );
}




